251	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
252	        if (from.getId().equals(to.getId())) {
253	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
254	        }
255	        requireNotRetired(to, claim.getDate());
256	        correctedNumber(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
257	        RollupService.Rollup before = rollups.snapshot(sheetId);
258	        claim.setPersonId(to.getId());
259	        claim.unbind();
260	        Claim saved = claims.saveAndFlush(claim);
261	        audit(sheetId, user, "CLAIM_REASSIGNED", to, saved, saved.getNumber(),
262	                " from=" + from.getName() + " to=" + to.getName());
263	        rollups.recordChanges(sheetId, user, before);
264	        return saved;
265	    }
266	
267	    /** The pending claim a steward acts on; refused when it is not pending, not dated in an open period, or the user is no steward. */
268	    private Claim pending(Sheet sheet, String user, long claimId) {
269	        Claim claim = claims.findByIdAndSheetId(claimId, sheet.getId())
270	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
271	        periods.requireOpenOn(sheet.getId(), claim.getDate());
272	        if (claim.getStatus() != ClaimStatus.PENDING) {
273	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim is not pending");
274	        }
275	        if (settings.roleOf(sheet.getId(), user) != Role.STEWARD) {
276	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
277	        }
278	        return claim;
279	    }
280	
281	    /** A settled claim's due field, for the end of its audit line. */
282	    private static String dueField(Claim claim) {
283	        return " due=" + (claim.getDue() == null ? "n/a" : claim.getDue().setScale(2).toPlainString());
284	    }
285	
286	    /** How many of the claims asked for a bulk open were opened, and how many were refused. */
287	    public record BulkOpened(int opened, int refused) {
288	    }
289	
290	    /**
291	     * Open each of these claims that can be opened, numbering them in list order (the people's order,
292	     * then their claims as listed, newest first); each that cannot is refused and left as it is.
293	     * Each is opened in a transaction of its own, so a refused one rolls back only itself.
294	     */
295	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
296	        Set<Long> wanted = new HashSet<>(claimIds);
297	        Map<Long, Integer> personOrder = new HashMap<>();
298	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
299	        for (int i = 0; i < listed.size(); i++) personOrder.put(listed.get(i).getId(), i);
300	        List<Claim> chosen = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
301	                .filter(c -> wanted.contains(c.getId()))
302	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
303	                        .thenComparing(Claim::getId, Comparator.reverseOrder()))
304	                .toList();
305	        int opened = 0;
306	        for (Claim c : chosen) {
307	            try {
308	                transactions.executeWithoutResult(t -> changeStatus(sheetId, user, c.getId(), ClaimStatus.OPEN));
309	                opened++;
310	            } catch (ResponseStatusException refused) {
311	                // Left as it is: every check comes before any change.
312	            }
313	        }
314	        return new BulkOpened(opened, wanted.size() - opened);
315	    }
316	
317	    /**
318	     * Take a statement for a person on the sheet's today: their due-total then (the sum of the figures
319	     * of their claims that count, a held person's open ones not among them; n/a when the grade in force
320	     * today has no rate in force then and none of those claims has a figure; late charges in) is recorded, and each claim that counts is bound to its
321	     * figure then (its late charge not bound: it keeps following the sheet's today), the others left unbound. Their claims, newest first.
322	     */
323	    @Transactional
324	    public List<Claim> statement(String sheetId, String user, long personId) {
325	        Sheet sheet = sheets.lock(sheetId, user);
326	        Person person = people.findByIdAndSheetId(personId, sheetId)
327	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
328	        RollupService.Rollup before = rollups.snapshot(sheetId);
329	        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
330	                .filter(c -> c.getPersonId().equals(personId))
331	                .toList();
332	        List<Claim> counting = theirs.stream().filter(c -> RollupService.counts(person, c)).toList();
333	        boolean rated = rates.findInForce(sheetId, person.gradeOn(sheet.getToday()), sheet.getToday()).isPresent();
334	        boolean anyFigure = false;
335	        BigDecimal total = BigDecimal.ZERO.setScale(2);
336	        for (Claim c : theirs) {
337	            if (RollupService.counts(person, c)) {
338	                BigDecimal figure = figure(sheetId, person, c);
339	                if (figure != null) total = total.add(figure);
340	                anyFigure |= figure != null;
341	                c.bind(rollups.boundFigure(sheetId, person, c));
342	            } else {
343	                c.unbind();
344	            }
345	        }
346	        claims.saveAllAndFlush(theirs);
347	        BigDecimal dueTotal = rated || anyFigure ? total : null;
348	        statements.saveAndFlush(new Statement(sheetId, personId, sheet.getToday(), dueTotal, counting.size(), user));
349	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
350	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString())
351	                + " claims=" + counting.size());
352	        rollups.recordChanges(sheetId, user, before);
353	        return theirs;
354	    }
355	
356	    /** The figure a claim shows (see {@link RollupService#figure}); null when none. */
357	    private BigDecimal figure(String sheetId, Person person, Claim claim) {
358	        return rollups.figure(sheetId, person, claim);
359	    }
360	
361	    /**
362	     * Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd; a claim
363	     * with a number (a voided one keeps it) ends with it.
364	     */
365	    private void audit(String sheetId, String user, String event, Person person, Claim claim, String number) {
366	        audit(sheetId, user, event, person, claim, number, "");
367	    }
368	
369	    /** As above, with {@code suffix} (fields a later change added) at the end of the line. */
370	    private void audit(String sheetId, String user, String event, Person person, Claim claim, String number,
371	            String suffix) {
372	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
373	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
374	                + (number != null ? " number=" + number : "") + suffix);
375	    }
376	
377	    /**
378	     * The number a claim being opened gets: while the sheet numbers by period (its period numbering
379	     * from-date is set and its today is on or after it), the next in the sequence of the period the
380	     * claim's date falls in, as {@code <period name>-<n>}, or {@code X-<n>} for one in no period; else
381	     * the next sheet-wide number.
382	     */
383	    private String nextNumber(Sheet sheet, Claim claim) {
384	        if (!sheet.numbersByPeriod()) return String.valueOf(sheet.takeClaimNumber());
385	        String prefix = periods.periodOn(sheet.getId(), claim.getDate()).map(Period::getName).orElse(NO_PERIOD);
386	        ClaimNumberSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
387	                .orElseGet(() -> new ClaimNumberSequence(sheet.getId(), prefix));
388	        int n = sequence.take();
389	        sequences.saveAndFlush(sequence);
390	        return prefix + "-" + n;
391	    }
392	
393	    /**
394	     * Whether a settle needs a steward's approval: a clerk settling a claim whose due is above the
395	     * sheet's clerk limit (one with no due, n/a, is not above it); a steward settles any.
396	     */
397	    private boolean needsApproval(Sheet sheet, String user, Person person, Claim claim) {
398	        BigDecimal limit = sheet.getClerkLimit();
399	        if (limit == null || settings.roleOf(sheet.getId(), user) == Role.STEWARD) {
400	            return false;
401	        }
402	        BigDecimal due = figure(sheet.getId(), person, claim);
403	        return due != null && due.compareTo(limit) > 0;
404	    }
405	
406	    /**
407	     * The number a claim of this amount corrects: none for one of 0.00 or more; a correction (a
408	     * negative amount) must name a settled claim of the same person, else it is refused.
409	     */
410	    private String correctedNumber(String sheetId, long personId, BigDecimal amount, String corrects) {
411	        if (amount.signum() >= 0) return null;
412	        boolean settled = corrects != null && claims.findBySheetIdOrderByIdDesc(sheetId).stream()
413	                .anyMatch(c -> c.getPersonId() == personId && corrects.equals(c.getNumber())
414	                        && c.getStatus() == ClaimStatus.SETTLED);
415	        if (!settled) {
416	            throw new ResponseStatusException(HttpStatus.CONFLICT,
417	                    "A correction must name a settled claim of the same person");
418	        }
419	        return corrects;
420	    }
421	
422	    /** Refuse a claim dated after the person's retirement. */
423	    private static void requireNotRetired(Person person, LocalDate date) {
424	        if (person.retiredOn(date)) {
425	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated after the person retired");
426	        }
427	    }
428	
429	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
430	        return date != null ? date : sheets.today(sheetId);
431	    }
432	
433	    private static String noteOf(String note) {
434	        return note == null ? "" : note.trim();
435	    }
436	}
